516: // Whole-line OO-DTC model.  Unlike io_frontend, physical-line lifetime is
517: // protected by one Ref per live coalesced 128B reference, and any oldest-ready
518: // PIB entry may retire.  It has no dependency on conventional L1D MSHRs.
519: class oo_frontend {
520:  public:
521:   explicit oo_frontend(config cfg)
522:       : m_cfg(cfg),
523:         m_tags(cfg.logical_sets * cfg.logical_ways),
524:         m_phys(cfg.physical_lines),
525:         m_slots(cfg.oo_pib_entries) {
526:     check_tag_hash_bankrow(cfg.tag_hash_bankrow,
527:                            cfg.selected_mode == mode::PAPER_OO,
528:                            cfg.finite_service, cfg.logical_sets, cfg.tag_banks);
529:     check_progressive_wakeup_mode(cfg.progressive_wakeup,
530:         static_cast<unsigned>(cfg.selected_mode), cfg.finite_service);
531:     assert(cfg.logical_sets && cfg.logical_ways && cfg.physical_lines);
532:     assert(cfg.allocation_width && cfg.oo_pib_entries);
533:     assert(cfg.ref_count_bits && cfg.ref_count_bits < 32);
534:     assert(cfg.tag_banks && cfg.tag_requests_per_bank_per_cycle &&
535:            cfg.tag_requests_per_cycle);
536:   }
