544:   bool admit(uint64_t uid) {
545:     if (find_entry(uid)) return true;
546:     if (m_entries.size() >= m_cfg.oo_pib_entries) return false;
547:     unsigned slot = 0;
548:     for (; slot < m_slots.size(); ++slot)
549:       if (!m_slots[slot].active) break;
550:     assert(slot < m_slots.size());
551:     slot_state &state = m_slots[slot];
552:     state.active = true;
553:     state.uid = uid;
554:     ++state.generation;
555:     m_entries.push_back({uid, slot, state.generation, {}, 0});
556:     assert_shadow_refs();

571:   bool try_serve_tag(uint64_t cycle, uint64_t address) {
572:     if (cycle != m_tag_cycle) {
573:       m_tag_cycle = cycle;
574:       std::fill(m_tag_requests_this_cycle.begin(),
575:                 m_tag_requests_this_cycle.end(), 0);
576:       m_total_tag_requests_this_cycle = 0;
577:     }
578:     const unsigned set = tag_set(address);
579:     const unsigned bank = set % m_cfg.tag_banks;
580:     if (m_total_tag_requests_this_cycle >= m_cfg.tag_requests_per_cycle ||
581:         m_tag_requests_this_cycle[bank] >=
582:             m_cfg.tag_requests_per_bank_per_cycle) {
583:       ++m_tag_conflicts;
584:       return false;
585:     }
586:     ++m_total_tag_requests_this_cycle;
587:     ++m_tag_requests_this_cycle[bank];
588:     ++m_tag_requests;
589:     return true;

597:     const uint64_t line = address & ~(kLogicalLineBytes - 1);
598:     return find_tag(line) == nullptr;
599:   }
