601:   // Lane X K1: atomic, zero additional simulated-cycle directory sweep at
602:   // the existing LD/ST source REQUEST. Does not advance service or touch any
603:   // consumer/return identity. Only a fully finished, Ref-free line can free.
604:   lookup_invalidation_result invalidate_lookup(uint64_t cycle) {
605:     lookup_invalidation_result result;
606:     assert_shadow_refs();
607:     for (tag_entry &tag : m_tags) {
608:       if (!tag.valid) continue;
609:       physical_line &physical = m_phys[tag.physical.id];
610:       assert(fill_identity_matches(tag.physical) && physical.tag_valid);
611:       tag.valid = false;
612:       physical.tag_valid = false;
613:       ++result.changed;
614:       if (m_cfg.finite_service) {
615:         const bool inserted =
616:             m_service_map_loss.emplace(tag.physical.id, cycle).second;
617:         assert(inserted && "one map-loss timestamp per allocated generation");
618:       }
619:       if (physical.ref_count) {
620:         ++result.retained;
621:       } else {
622:         // In the read lifecycle every pending lower/service/collection owner
623:         // keeps a live consumer Ref. Ref=0 may only be a finished retained hit.
624:         assert(physical.ready && physical.waiters.empty());
625:         for (const auto &pending : m_service_returns)
626:           assert(pending.physical.id != tag.physical.id ||
627:                  pending.physical.generation != tag.physical.generation);
628:         release(tag.physical, cycle);
629:         ++result.reclaimed;
630:       }
631:     }
632:     assert(result.changed == result.retained + result.reclaimed);
633:     assert_shadow_refs();
634:     return result;

637:   io_access_result access(uint64_t cycle, uint64_t uid, uint64_t address) {
638:     begin_cycle(cycle);
639:     entry *owner = find_entry(uid);
640:     assert(owner);
641:     const uint64_t line = address & ~(kLogicalLineBytes - 1);
642:     tag_entry *tag = find_tag(line);
643:     if (tag) {
644:       attach_reference(*owner, tag->physical);
645:       ++(m_phys[tag->physical.id].ready ? m_valid_hits : m_pending_hits);
646:       assert_shadow_refs();
647:       return {m_phys[tag->physical.id].ready ? io_access_kind::VALID_HIT
648:                                               : io_access_kind::PENDING_HIT,
649:               tag->physical};
650:     }
651:     if (m_allocations_this_cycle >= m_cfg.allocation_width) {
652:       ++m_allocation_width_limited_events;
653:       return {io_access_kind::NO_FREE_LINE, {}};
654:     }
655: 
656:     tag_entry *victim = select_victim(line);
657:     int free_id = find_free_physical();
658:     const bool can_reclaim_victim =
659:         victim->valid && m_phys[victim->physical.id].ref_count == 0;
660:     if (free_id < 0 && !can_reclaim_victim) {
661:       ++m_no_free_physical_events;
662:       return {io_access_kind::NO_FREE_LINE, {}};
663:     }
664:     if (victim->valid) {
665:       physical_line &old = m_phys[victim->physical.id];
666:       assert(old.allocated && old.tag_valid);
667:       old.tag_valid = false;
668:       if (m_cfg.finite_service) m_service_map_loss[victim->physical.id] = cycle;
669:       ++m_tag_evictions;
670:       if (old.ref_count == 0) {
671:         release(victim->physical);
672:         ++m_immediate_reclaims;
673:       } else {
674:         ++m_deferred_reclaims;
675:       }
676:     }
677:     if (free_id < 0) free_id = find_free_physical();
678:     assert(free_id >= 0);
679:     physical_line &physical = m_phys[free_id];
680:     physical.allocated = true;
681:     physical.ready = false;
682:     if (m_cfg.progressive_wakeup) {
683:       physical.data_ready = false;
684:       physical.return_cycle = UINT64_MAX;
685:       physical.first_notify_cycle = physical.last_notify_cycle = UINT64_MAX;
686:       physical.notified = physical.late_merges = 0;
687:     }
688:     physical.tag_valid = true;
689:     physical.ref_count = 0;
690:     physical.waiters.clear();
691:     physical_identity identity{static_cast<unsigned>(free_id),
692:                                ++physical.generation};
693:     *victim = {true, line, identity, ++m_lru_clock};
694:     attach_reference(*owner, identity);
695:     ++m_allocations_this_cycle;
696:     ++m_new_misses;
697:     assert_shadow_refs();
698:     return {io_access_kind::NEW_MISS, identity};

709:   void complete(physical_identity identity) {
710:     assert(fill_identity_matches(identity) &&
711:            "OO fill must match the original physical generation");
712:     physical_line &physical = m_phys[identity.id];
713:     assert(!physical.ready && "OO fill must wake each waiter exactly once");
714:     if (m_cfg.finite_service) {
715:       assert(m_service_cycle != UINT64_MAX);
716:       for (const auto &pending : m_service_returns)
717:         assert(pending.physical.id != identity.id ||
718:                pending.physical.generation != identity.generation);
719:       if (m_cfg.progressive_wakeup) physical.return_cycle = m_service_cycle;
720:       m_service_returns.push_back({identity, m_service_cycle + 1, 0});
721:       return;
722:     }
723:     physical.ready = true;
724:     for (const waiter &waiting : physical.waiters) {
725:       entry *owner = find_entry_by_slot(waiting.slot, waiting.slot_generation);
726:       assert(owner && has_reference(*owner, identity) &&
727:              "stale fill cannot wake a reused OO PIB slot");
728:       assert(owner->pending_dependencies);
729:       --owner->pending_dependencies;
730:       ++m_wakeups;
731:     }
732:     physical.waiters.clear();
733:     assert_shadow_refs();
734:   }
